 out=R/'experiments/prospective_external_family_prediction_input_bundle_v1_2026-10-19';out.mkdir(exist_ok=False);ep=R/'experiments/prospective_external_family_development_endpoints_v1_2026-10-19/endpoints.json';e=read(ep);qs={q['connection_id']:q for q in e['connections']};assert len(qs)==len(e['connections'])==15616;timing=R/'experiments/prospective_external_family_current_initial_timing_v1_2026-10-19';tag=epoch(timing);critical=load(timing,ep,expected_epoch=tag);floorroot=R/'experiments/prospective_external_family_raw_floors_v1_2026-10-19';floorproof=floorroot/'independent_verification_v1.json';fv=read(floorproof);assert fv['connections']==15616 and all(sha(p)==h for p,h in fv['bindings'].items());floorprotocol=read(floorroot/'protocol.json');graph=Path(e['inputs']['graph']['path']);assert floorprotocol['bindings'][str(graph)]==sha(graph)==e['graph_sha256'];floors={f['connection_id']:f for f in map(json.loads,(floorroot/'floors.jsonl').open())};assert set(floors)==set(qs)==set(critical)
