 bundle=dict(status='CURRENT_GRAPH_ALL15616_FORECAST_INPUT_IDENTITIES_AND_LATTICES_ADMITTED',connections=15616,NETs=len({q['net_id'] for q in qs.values()}),graph_nodes=119878,graph_sha256=e['graph_sha256'],timing_epoch_sha256=tag,raw_delay_scale=10**18,node_base_scale=10**18,all_CIDs_have_floor_and_current_float32_criticality=True,all_node_prices_nonnegative_uint64=True,budgets_assigned=False,source_contract='Conditional-reset original source proof plus separately explicit-ground packed Boolean certificate; default-X and unrestricted HDL scopes remain separate.',family_role='Unknown-history development inputs only, not strict unseen family or promoted predictor.',required_forecast_protocol=['Bind source-conditioning route and three deterministic independent target-swap input roles before any corresponding target labels.','Bind complete actual baseline/predictor/native commands, all widths/layout failures, quality metrics and unchanged gates.','State additive floor-based budget rule explicitly; worst-path slack is not a per-connection additive budget.','Exclude structural SOURCE root explicitly when applying shared-NET node-base objective; no silent zeroing of native input.','Include graph-local floor, capture, input conversion, candidate banks, prediction, audit and final exact native-routing costs.'],next_action='Freeze an executable full development workflow protocol using this input bundle, preserving prior failures/controls and unknown-history status, before any source or target routing trial. Do not substitute a successful input admission for forecast/native utility gates.',bindings={str(p):sha(p) for p in paths})
